use sequoia_openpgp as openpgp;
use openpgp::crypto::mpi::SecretKeyMaterial;
use openpgp::packet::key::{Key4, UnspecifiedRole};

const COUNT: usize = 100;
const SIZES: [usize; 4] = [1024, 2048, 3072, 4096];

// Usage: cargo run --release --example generate-rsa-test-keys > rsa.rs.inc
fn main() -> openpgp::Result<()> {
    println!(
        "// Generated by openpgp/examples/generate-rsa-test-keys.rs; \
         do not edit.");
    println!("static POOLS: [Pool; {}] = [", SIZES.len());
    for bits in SIZES {
        eprintln!("Generating {} {}-bit RSA test keys...", COUNT, bits);
        println!("    Pool::new({}, &[", bits);
        for _ in 0..COUNT {
            let key = Key4::<_, UnspecifiedRole>::generate_rsa(bits)?
                .into_keypair()?;
            key.secret().map(|secret| {
                let SecretKeyMaterial::RSA { d, p, q, .. } = secret else {
                    unreachable!("generated an RSA key");
                };
                println!("        RsaKey {{");
                for (name, value) in [("d", d), ("p", p), ("q", q)] {
                    print!("            {}: b\"", name);
                    for byte in value.value() {
                        print!("\\x{:02x}", byte);
                    }
                    println!("\",");
                }
                println!("        }},");
            });
        }
        println!("    ]),");
    }
    println!("];");
    Ok(())
}
